// Custom sampler stubs (mapped to noise texture)
#define sampler_pw_noise_lq sampler_noise_lq
#define sat clamp01
sampler sampler_pw_noise_lq;
const float quality = 4;
vec3 rsl, rsl3, ret1, sky, mod;
vec2 dz, uv0, uv1, uv2, uv3, uv4, uvc, dz1;
float  lav_gnd,lav_gnd2, smask, ripple, l,d,i,p;
const float hory = q6, xyscale = q7, alti = q8;
const vec2 hor = (vec2(1.0)/uTexSize)*vec2 (1.5, 0.0 ), dir = vec2 (q3, q4), modran = vec2 (q15,q16);
const vec3 mov = vec3 (q10,q11, 0.0 );
float comb (vec2 uvi) {return dot (texture(sampler_noise_lq, uvi).yx, vec2( 1.0 , 1.0 ));}
vec2 noise2 (vec2 uvi) {vec2 tmp = 1; float s = 1;
for (int n = 1; n <= 2; n +=1 ) {tmp *= 1-texture(sampler_noise_lq,uvi*s); s*= 3;}
return tmp;}
vec2 noise3 (vec3 uvi, vec3 mod) {uvi *= 0.16; vec2 tmp = 1; float s = 1; float diff = 0;
uvi.xy+= modran * 3.0;
for (int n = 1; n <= 2; n +=1 ) {tmp *= sat(1-texture(sampler_noise_lq,uvi*s)*(0.8+mod.y/2)/s); s*= 3+tmp*0.002*mod.z;}
for (int n = 1; n <= 3; n +=1 ) {tmp *= sat(1-texture(sampler_noise_lq,uvi*s)*(0.8+mod.y/2)/s); s*= 3;}
diff = sat (16-2*uvi.z - 20000.0* abs (tmp.x-0.4)) ;
tmp  -= diff*0.009 ;
return 1.0 - pow (tmp,0.8+mod.x);}
vec2 enoise3 (vec2 uvi, vec3 mod) {uvi/=6; vec2 tmp = 1; float s = 1;
for (int n = 1; n <= 6; n +=1 ) {tmp *= 1-texture(sampler_noise_lq,uvi*s)/(0.8+mod.y)/s; s*= 2.9;}
if ((tmp.x > 0.398) && (tmp.x < 0.402)) {tmp = 0.398;}
return 1.0 - pow (tmp,.8+2*mod.x);}
vec3 rs_lav (vec2 uvi, float berg) {  float z; vec2 rs;
z = 1.0 / (uvi.y+hory)*(alti-berg * 16.0); //z = clamp(z, 0.0 ,4.0 / xyscale);
rs.x = uvi.x * 2.0*z ; rs.y = z;
return vec3(rs*xyscale,z); }
l = clamp01(-lav_gnd);
d=1.8;
dz = -1.5/rsl.z*xyscale*d*dir;
rsl3 = rsl * 8.0 + l * 0.0;
ripple = ((noise2 (rsl3-dz) - noise2 (rsl3+dz))* (1.0 - l)) * 1.0+0.02;
ripple = (1.0 / rsl.z*ripple+noise3 (rsl-vec3 (dz, 0.0 ),mod) - noise3 (rsl+vec3 (dz, 0.0 ),mod))*(1.0 - l)/d/sqrt(50.0 + rsl.z) * 2000.0;
ripple = 1.0 - exp(-ripple);
ret.r = ripple;
ret.b = l;
ret = mix(ret,GetBlur1(uv),0.1);
ret.g = rsl.z*xyscale * 4.0;
}

void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  uv1=uv-0.5;
lav_gnd=  -min (texture(sampler_fc_main,uv).b, texture(sampler_fc_main,uv+hor.yx).b);
rsl = rs_lav(uv1,lav_gnd)+mov;
mod = texture(sampler_noise_mq,rsl.xy*.043+modran);
i=0, p=0;
for (int n=1; n <= quality; n++) {
p =  ((lav_gnd+noise3 (rsl, mod))/quality);
i += p;
lav_gnd -= p*0.1+i*0.2;
rsl = rs_lav(uv1,lav_gnd)+mov;
  fragColor = vec4(ret, 1.0);
}

